1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
10	import org.springframework.web.bind.annotation.RequestBody;
11	
12	/**
13	 * Validates a new owner before {@link BuildOwner} runs: every one of firstName, lastName, address,
14	 * city and telephone must be present and non-blank. Any that are missing or blank are collected and
15	 * reported together as a {@link MissingOwnerFieldsException} (a 400), so the body is never persisted.
16	 *
17	 * <p>The telephone is then normalized by stripping every non-digit character and must be exactly ten
18	 * digits; otherwise an {@link InvalidTelephoneException} (a 400) is raised. The stripped value is
19	 * written back onto the request so downstream steps store and return the 10-digit telephone.
20	 *
21	 * <p>Deliberately does <em>not</em> use {@code @Valid}: bean validation would raise a
22	 * {@code MethodArgumentNotValidException} with a different response shape, whereas this rule must
23	 * answer with an {@code errors} array naming each offending field.
24	 */
25	public class ValidateNewOwner {
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws MissingOwnerFieldsException, InvalidTelephoneException {
29	        // This list mirrors OwnerFieldsDto's required fields by hand: it must track the schema's
30	        // `required` set. We check presence/non-blankness only, a narrower rule than the DTO's full
31	        // constraints (@Size/@Pattern), so bean validation is intentionally not used here.
32	        List<String> missing = new ArrayList<>();
33	        require(missing, "firstName", request.getFirstName());
34	        require(missing, "lastName", request.getLastName());
35	        require(missing, "address", request.getAddress());
36	        require(missing, "city", request.getCity());
37	        require(missing, "telephone", request.getTelephone());
38	        if (!missing.isEmpty()) {
39	            throw new MissingOwnerFieldsException(missing);
40	        }
41	
42	        // Normalize the telephone: keep only digits, then require exactly ten. Store the stripped
43	        // value back so BuildOwner/SaveOwner persist it and the response echoes the 10-digit form.
44	        String normalized = request.getTelephone().replaceAll("\\D", "");
45	        if (normalized.length() != 10) {
46	            throw new InvalidTelephoneException(normalized);
47	        }
48	        request.setTelephone(normalized);
49	
50	        validated.set(request);
51	    }
52	
53	    private static void require(List<String> missing, String field, String value) {
54	        if (value == null || value.isBlank()) {
55	            missing.add(field);
56	        }
57	    }
58	}
