1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a request to create an owner carries a telephone that, once every non-digit
5	 * character is stripped, is not exactly ten digits. Carries the normalized (digits-only)
6	 * value so {@link InvalidTelephoneExceptionHandler} can report what was actually seen.
7	 * Checked so it appears in the function's {@code throws} clause and is routed as an escalation.
8	 */
9	public class InvalidTelephoneException extends Exception {
10	
11	    private final String normalized;
12	
13	    public InvalidTelephoneException(String normalized) {
14	        super("Telephone must be exactly 10 digits after removing non-digit characters, but was "
15	                + normalized.length() + ": '" + normalized + "'");
16	        this.normalized = normalized;
17	    }
18	
19	    public String getNormalized() {
20	        return this.normalized;
21	    }
22	}
