3	import net.officefloor.plugin.section.clazz.Parameter;
4	import net.officefloor.web.ObjectResponse;
5	import org.springframework.http.HttpStatus;
6	import org.springframework.http.ProblemDetail;
7	import org.springframework.http.ResponseEntity;
8	
9	/**
10	 * Responds 400 with an RFC-7807 {@link ProblemDetail} (built through the shared {@link ProblemDetails}
11	 * helper, like every other handler in this package) when a new owner's telephone is not exactly ten
12	 * digits once non-digit characters are stripped.
13	 */
14	public class InvalidTelephoneExceptionHandler {
15	
16	    public void handle(@Parameter InvalidTelephoneException ex,
17	            ObjectResponse<ResponseEntity<ProblemDetail>> response) {
18	        ProblemDetail detail = ProblemDetails.build(ex, HttpStatus.BAD_REQUEST,
19	                "The telephone must be exactly 10 digits after removing non-digit characters");
20	        detail.setProperty("errors", java.util.List.of("telephone"));
21	        response.send(ResponseEntity.status(HttpStatus.BAD_REQUEST).body(detail));
22	    }
23	}
